-- All business tables live outside the exposed PostgREST schemas. Never expose shop in API settings.
begin;
create schema shop;
create role paradelle_runtime nologin noinherit nosuperuser nobypassrls;
revoke all on schema shop from public;
grant usage on schema shop to paradelle_runtime,authenticated;
create table shop.profiles(id uuid primary key references auth.users(id),email text not null unique,full_name text not null,role text not null check(role='admin'),is_active boolean not null default false,permissions text[] not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table shop.staff_sessions(digest text primary key,admin_id uuid not null references shop.profiles,expires_at timestamptz not null);
create table shop.store_settings(singleton boolean primary key default true check(singleton),revision integer not null default 0,sections jsonb not null default '{}',shipping_paise integer check(shipping_paise>=0),free_from_paise integer check(free_from_paise>=0),serviceable_pins text[] not null default '{}',updated_at timestamptz not null default now());
insert into shop.store_settings default values; -- Empty configuration, no assumed shipping rate or coverage.
create table shop.products(id uuid primary key default gen_random_uuid(),title text not null,slug text,sku text,short_description text not null default '',description text not null default '',category text not null default '',fabric text not null default '',pattern text not null default '',sleeve_type text not null default '',neck_style text not null default '',kurti_length text not null default '',occasion text not null default '',colour text not null default '',care_instructions text not null default '',seo_title text not null default '',seo_description text not null default '',source_url text,source_price integer check(source_price>=0),purchase_cost integer check(purchase_cost>=0),selling_price integer check(selling_price>0),compare_at_price integer check(compare_at_price>0),status text not null default 'draft' check(status in ('draft','published','archived')),is_featured boolean not null default false,is_bestseller boolean not null default false,published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),revision integer not null default 1,details jsonb not null default '{}', check(status<>'published' or (selling_price is not null and slug is not null and published_at is not null)));
create unique index products_slug on shop.products(slug) where slug is not null;create unique index products_sku on shop.products(lower(sku)) where sku is not null;
create index product_discovery on shop.products(category,published_at desc,id) where status='published';create index product_register_idx on shop.products(status,updated_at desc,id);
create table shop.assets(id uuid primary key default gen_random_uuid(),bucket text not null check(bucket in ('product-images','site-assets')),storage_path text not null unique,purpose text not null check(purpose in ('product','logo','reference','generated')),width integer not null check(width>0),height integer not null check(height>0),alt text not null default '',rights_confirmed boolean not null check(rights_confirmed),created_by uuid not null references shop.profiles,created_at timestamptz not null default now());
create table shop.product_images(id uuid primary key default gen_random_uuid(),product_id uuid not null references shop.products on delete cascade,asset_id uuid not null references shop.assets,storage_path text not null,image_order integer not null check(image_order>=0),image_type text not null,alt_text text not null,is_primary boolean generated always as(image_order=0) stored,generation_provider text,generation_job_id uuid,created_at timestamptz not null default now(),unique(product_id,image_order),unique(product_id,asset_id));create index product_image_asset on shop.product_images(asset_id);
create table shop.product_variants(id uuid primary key,product_id uuid not null references shop.products on delete cascade,sku text,size text not null,colour text,stock_quantity integer not null check(stock_quantity between 0 and 1000000),is_available boolean not null,variant_price_override integer check(variant_price_override>0),low_threshold integer not null default 3,revision integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(product_id,size));create unique index variant_sku on shop.product_variants(lower(sku)) where sku is not null;
create table shop.stock_history(id uuid primary key default gen_random_uuid(),variant_id uuid not null,product_id uuid not null,product text not null,size text not null,sku text not null,before_qty int not null,delta int not null,after_qty int not null,reason text not null,actor text not null,created_at timestamptz not null default now(),check(before_qty+delta=after_qty and after_qty>=0 and delta<>0));create index stock_history_recent on shop.stock_history(created_at desc);
create table shop.coupons(id uuid primary key default gen_random_uuid(),code text not null unique check(code=upper(code)),discount_type text not null check(discount_type in ('fixed','bps')),discount_value int not null check(discount_value>0),minimum_order_value int not null default 0,maximum_discount int check(maximum_discount>=0),usage_limit int check(usage_limit>0),usage_count int not null default 0,start_at timestamptz not null default now(),expiry_at timestamptz,is_active boolean not null default false,created_at timestamptz not null default now(),check(discount_type<>'bps' or discount_value<=10000));
create table shop.customers(id uuid primary key default gen_random_uuid(),full_name text not null,phone_number text not null,normalised_phone text not null unique check(normalised_phone ~ '^[6-9][0-9]{9}$'),email text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table shop.addresses(id uuid primary key default gen_random_uuid(),customer_id uuid not null references shop.customers,full_name text not null,phone_number text not null,address_line_1 text not null,address_line_2 text,city text not null,state text not null,pincode text not null check(pincode~'^[1-9][0-9]{5}$'),country text not null default 'IN' check(country='IN'),created_at timestamptz not null default now());
create table shop.checkout_intents(id uuid primary key default gen_random_uuid(),owner_hash text not null,request_id uuid not null,input_hash text not null,address jsonb,email text,lines jsonb not null,subtotal int not null,discount int not null,shipping int not null,tax int not null,total int not null check(total>=100 and total=subtotal-discount+shipping),currency text not null default 'INR' check(currency='INR'),coupon_id uuid references shop.coupons,provider_order text unique,provider_claim timestamptz,state text not null default 'quoted' check(state in ('quoted','opened','paid','expired')),expires_at timestamptz not null,created_at timestamptz not null default now(),unique(owner_hash,request_id));create index intent_owner on shop.checkout_intents(owner_hash,created_at desc);create index intent_expiry on shop.checkout_intents(expires_at) where state<>'paid';
create table shop.reservations(intent_id uuid not null references shop.checkout_intents on delete cascade,variant_id uuid not null references shop.product_variants,quantity int not null check(quantity>0),expires_at timestamptz not null,primary key(intent_id,variant_id));create index stock_holds on shop.reservations(variant_id,expires_at);
create sequence shop.order_serial;
create function shop.next_order_number() returns text language sql volatile set search_path='' as $$select 'PAR-'||lpad(n,greatest(5,length(n)),'0') from (select nextval('shop.order_serial')::text n) s$$;
revoke all on function shop.next_order_number() from public; grant execute on function shop.next_order_number() to paradelle_runtime;grant usage on sequence shop.order_serial to paradelle_runtime;
create table shop.orders(id uuid primary key default gen_random_uuid(),order_number text not null unique default shop.next_order_number(),intent_id uuid not null unique references shop.checkout_intents,customer_id uuid not null references shop.customers,address_id uuid not null references shop.addresses,customer_name_snapshot text not null,customer_phone_snapshot text not null,delivery_address_snapshot jsonb not null,subtotal integer not null,discount_amount integer not null,shipping_amount integer not null,tax_amount integer not null,total_amount integer not null check(total_amount=subtotal-discount_amount+shipping_amount),payment_status text not null check(payment_status in ('paid','refund-pending','partially-refunded','refunded')),fulfilment_status text not null default 'pending-purchase' check(fulfilment_status in ('pending-purchase','ordered-on-meesho','shipped','delivered','cancelled')),exception_reason text,currency text not null check(currency='INR'),revision int not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now());create index order_customer on shop.orders(customer_id,created_at desc);create index order_tracking on shop.orders(customer_phone_snapshot,created_at desc);create index order_status on shop.orders(fulfilment_status,created_at desc);create index order_paid on shop.orders(created_at desc,id);
create table shop.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references shop.orders,product_id uuid not null references shop.products,product_title_snapshot text not null,product_image_snapshot text,selected_size text not null,selected_variant_id uuid not null,quantity int not null check(quantity>0),unit_price int not null,total_price int not null check(total_price=unit_price*quantity),source_cost_snapshot int,source_url_snapshot text,category_snapshot text not null,gst_bps int not null,variable_cost_snapshot int,created_at timestamptz not null default now());create index order_lines on shop.order_items(order_id);create index order_products on shop.order_items(product_id);
create table shop.payments(id uuid primary key default gen_random_uuid(),order_id uuid not null unique references shop.orders,razorpay_order_id text not null unique,razorpay_payment_id text not null unique,razorpay_signature_verified boolean not null check(razorpay_signature_verified),amount int not null,currency text not null check(currency='INR'),status text not null check(status='captured'),method text,payment_metadata jsonb not null default '{}',paid_at timestamptz not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table shop.payment_events(event_id text primary key,kind text not null,created_at timestamptz not null default now());
create table shop.refunds(id uuid primary key default gen_random_uuid(),order_id uuid not null references shop.orders,payment_id text not null references shop.payments(razorpay_payment_id),provider_id text unique,amount int not null check(amount>0),reason text not null,status text not null default 'requested' check(status in ('requested','pending','processed','failed')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());create index refunds_order on shop.refunds(order_id,status);
create table shop.order_fulfilment(id uuid primary key default gen_random_uuid(),order_id uuid not null unique references shop.orders,source_platform text not null default 'Meesho',source_product_url text,source_order_id text,source_purchase_cost int check(source_purchase_cost>=0),actual_purchase_date date,carrier text,tracking_reference text,tracking_url text,fulfilment_status text not null default 'pending-purchase',admin_notes text,updated_by uuid references shop.profiles,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table shop.licensed_sources(source_url text primary key,licence_reference text not null,valid_until timestamptz not null,facts jsonb not null,reference_ids uuid[] not null default '{}',reviews jsonb not null default '[]' check(jsonb_array_length(reviews)<=10),created_at timestamptz not null default now());
create table shop.product_import_jobs(id uuid primary key default gen_random_uuid(),source_url text not null,source_product_id text not null,status text not null default 'pending',extraction_status text not null,extracted_data jsonb not null default '[]',generated_content jsonb,draft jsonb,content_status text not null default 'not-started',image_generation_status text not null default 'not-started',review_import_status text not null default 'not-started',images jsonb not null default '[]' check(jsonb_array_length(images)<=5),reviews jsonb not null default '[]' check(jsonb_array_length(reviews)<=10),reference_ids uuid[] not null default '{}',rights_confirmed boolean not null default false,product_id uuid unique references shop.products on delete set null,error_message text not null default '',retry_count int not null default 0,revision int not null default 1,created_by uuid not null references shop.profiles,created_at timestamptz not null default now(),updated_at timestamptz not null default now());create index import_recent on shop.product_import_jobs(updated_at desc);create index import_approval on shop.product_import_jobs(status);
create table shop.product_reviews(id uuid primary key default gen_random_uuid(),product_id uuid not null references shop.products on delete cascade,customer_id uuid references shop.customers,order_id uuid references shop.orders,rating int not null check(rating between 1 and 5),title text not null default '',review_text text not null,verification_status text not null check(verification_status in ('purchase','licensed')),publication_status text not null default 'pending' check(publication_status in ('pending','published','unpublished','rejected')),source text not null,licence_reference text,revision int not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(order_id,product_id),check((verification_status='purchase' and order_id is not null and customer_id is not null) or (verification_status='licensed' and order_id is null and licence_reference is not null)));create index public_reviews on shop.product_reviews(product_id,created_at desc) where publication_status='published';
create table shop.admin_activity_logs(id uuid primary key default gen_random_uuid(),admin_user_id uuid references shop.profiles,action text not null,entity_type text not null,entity_id uuid not null,metadata jsonb not null default '{}',created_at timestamptz not null default now());create index audit_entity on shop.admin_activity_logs(entity_type,entity_id,created_at desc);create index audit_recent on shop.admin_activity_logs(created_at desc);
create table shop.command_receipts(actor uuid not null references shop.profiles,key uuid not null,body_hash text not null,result jsonb not null,created_at timestamptz not null default now(),primary key(actor,key));
create table shop.work_queue(id uuid primary key default gen_random_uuid(),kind text not null check(kind in ('extract','content','image','refund','refund-check')),job_id uuid references shop.product_import_jobs,refund_id uuid references shop.refunds,slot int check(slot between 0 and 4),stage text not null default 'queued' check(stage in('queued','leased','waiting','done','failed','cancelled')),model text,reference_ids uuid[] not null default '{}',provider_id text,status_url text,response_url text,result_asset uuid references shop.assets,submitted_at timestamptz,lease uuid,lease_until timestamptz,run_after timestamptz not null default now(),attempts int not null default 0,poll_count int not null default 0,error text,created_at timestamptz not null default now());create index runnable_work on shop.work_queue(run_after,created_at) where stage in ('queued','leased','waiting');create index work_job on shop.work_queue(job_id);
create table shop.rate_windows(bucket text primary key,hits int not null,expires_at timestamptz not null);create index rate_expiry on shop.rate_windows(expires_at);
commit;
